extracted_python_code:
result = Customers.CALCULATE(
    cust_name=name,
    num_total_transactions=COUNT(transactions_made),
    num_successful_transactions=COUNT(transactions_made.WHERE(status == "Completed"))
).WHERE(
    num_total_transactions >= 5
).CALCULATE(
    customer_name=cust_name,
    success_rate=(num_successful_transactions * 100.0) / num_total_transactions
).ORDER_BY(
    success_rate.ASC()
)

result = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == "active")
).PARTITION(name="countries", by=country).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

top_2_frequent_buy_tickers = Tickers.CALCULATE(
    ticker_symbol=symbol,
    num_buy_transactions=COUNT(
        transactions_of.WHERE(
            (transaction_type == "buy") &
            (DATEDIFF("days", date_time, DATETIME('now')) <= 10)
        )
    )
).WHERE(num_buy_transactions > 0).TOP_K(2, by=num_buy_transactions.DESC())

result = Broker.CALCULATE(
    num_of_customers=COUNT(
        Customers.WHERE(
            (
                STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')
            ) & 
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

distinct_buy_customer_ids = Customers.WHERE(
    HAS(transactions_made.WHERE(transaction_type == 'buy')) == 1
).CALCULATE(
    customer_id_field=_id
)

recent_customers_transactions_count = Broker.CALCULATE(
    num_transactions_by_recent_users=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, 'now') <= 70
        ).transactions_made
    )
)

sales_by_salesperson_last_30_days = Salespersons.CALCULATE(
    salesperson_id_col=_id,
    salesperson_first_name=first_name,
    salesperson_last_name=last_name,
    num_sales_last_30_days=COUNT(
        sales_made.WHERE(
            (sale_date >= DATETIME('now', '-29 days')) & (sale_date <= DATETIME('now'))
        )
    )
).ORDER_BY(num_sales_last_30_days.DESC())

avg_days_sale_to_payment = Dealership.CALCULATE(
    average_lag_days=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_difference=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_difference
        ),
        2
    )
)

total_sales_count_last_7_days = Dealership.CALCULATE(
    total_sales_count_last_7_days=COUNT(
        Sales.WHERE(DATEDIFF("days", sale_date, 'now') <= 6)
    )
)

salespersons_with_cash_payments = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == "Cash")) == 1
).CALCULATE(
    salesperson_id_col=_id
)

top_revenue_sales_reps = Dealership.Salespersons.CALCULATE(
    rep_first_name=first_name,
    rep_last_name=last_name,
    total_revenue_amount=SUM(
        sales_made.WHERE(
            (sale_date >= DATETIME('now', '-3 months')) & (sale_date <= DATETIME('now'))
        ).sale_price
    ),
    total_sales_count=COUNT(
        sales_made.WHERE(
            (sale_date >= DATETIME('now', '-3 months')) & (sale_date <= DATETIME('now'))
        )
    )
).TOP_K(3, by=total_revenue_amount.DESC())

result = Dealership.CALCULATE(
    weekend_utility_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == "Utility Company") & 
            ((DAYOFWEEK(payment_date) == 1) | (DAYOFWEEK(payment_date) == 7))
        )
    )
)

result = DermTreatment.CALCULATE(
    num_patients_gmail_yahoo=COUNT(
        Patients.WHERE(
            (ENDSWITH(email, "@gmail.com")) | (ENDSWITH(email, "@yahoo.com"))
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count = COUNT(Patients.WHERE(
        HAS(treatments_received.WHERE(
            (diagnosis.diag_name == 'Psoriasis vulgaris') & 
            (drug.drug_type == 'Biologic')
        )) == 1
    ))
)

result = DermTreatment.CALCULATE(
    alice_treatments_last_6_months=COUNT(
        Patients.WHERE(first_name == "Alice").treatments_received.WHERE(
            (DATEDIFF("months", start_dt, DATETIME("now")) <= 6) &
            (DATEDIFF("months", start_dt, DATETIME("now")) >= 1)
        )
    )
)

avg_weight_drugalin_patients = DermTreatment.CALCULATE(
    average_weight_kg=AVG(
        Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg
    )
)

result = DermTreatment.CALCULATE(
    caw_male_patients=AVG(Patients.WHERE(gender == "Male").weight_kg)
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((gender == "Female") & (ins_type == "Private")))
)

result = Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1  # Ensure the diagnosis has associated treatments with outcome records
).CALCULATE(
    diagnosis_name = diag_name,
    maximum_itch_score = MAX(treatments_for.outcome_records.day100_itch_vas),
    number_of_patients = NDISTINCT(treatments_for.patient.patient_id)
).TOP_K(
    3,
    by = maximum_itch_score.DESC(na_pos='last')  # Order by max itch score, NULLs last
)

result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), "%psoriasis%") | LIKE(LOWER(diagnosis.diag_desc), "%psoriasis%")) &
            (drug.fda_appr_dt != None) &
            (DATEDIFF("months", end_dt, DATETIME("now")) <= 6)
        )
    )
)

result = DermTreatment.CALCULATE(
    avg_age_male_private = ROUND(AVG(
        Patients.WHERE(
            (gender == "Male") & 
            (ins_type == "Private")
        ).CALCULATE(
            age_years = DATEDIFF("years", date_of_birth, DATETIME("now"))
        ).age_years
    ), 0)
)

us_transactions_last_7_days = Transactions.WHERE(
    HAS(sending_user) == 1
).sending_user.WHERE(
    country == "US"
).transactions_sent.WHERE(
    DATEDIFF("days", created_at, DATETIME('now')) <= 7
)

result = Ewallet.CALCULATE(
    num_transactions=COUNT(us_transactions_last_7_days),
    total_amount=SUM(us_transactions_last_7_days.amount)
)

user_marketing_preferences = Users.CALCULATE(
    user_uid=uid,
    opt_in_status=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Users.CALCULATE(
    user_id=uid,
    total_duration=DEFAULT_TO(
        SUM(
            sessions.WHERE(
                (session_start_ts >= "2023-06-01") & (session_start_ts < "2023-06-08")
            ).CALCULATE(
                session_duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
            ).session_duration_seconds
        ),
        0
    )
).ORDER_BY(total_duration.DESC())

distinct_user_ids_with_transaction_notifications = Ewallet.Notifications.WHERE(
    CONTAINS(LOWER(notification_type), 'transaction')
).PARTITION(
    name="distinct_users", by=(user_id)
).CALCULATE(
    user_id=user_id
)

result = Ewallet.CALCULATE(
    median_balance = MEDIAN(
        Merchants.WHERE(
            (status == "active") & 
            CONTAINS(category, "retail")
        ).balances.WHERE(
            DATETIME(updated_at, 'start of day') == DATETIME('now', 'start of day')
        ).balance
    )
)

users_without_first_year_notifications = Users.WHERE(
    HASNOT(notifications.WHERE(
        DATEDIFF("days", created_at, notifications.created_at) <= 365
    )) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
